package com.cyancoder.dynamiccore.store.jpa;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="dynamic_entity_definition_versions",uniqueConstraints=@UniqueConstraint(columnNames={"serviceKey","tenantKey","siteKey","entityKey","revision"}))
public class StoredEntityDefinitionVersion{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String serviceKey;private String tenantKey;private String siteKey;private String entityKey;private long revision;private String status;@Column(columnDefinition="TEXT")private String definitionJson;private Instant createdAt;
 public Long getId(){return id;}public String getServiceKey(){return serviceKey;}public void setServiceKey(String v){serviceKey=v;}public String getTenantKey(){return tenantKey;}public void setTenantKey(String v){tenantKey=v;}public String getSiteKey(){return siteKey;}public void setSiteKey(String v){siteKey=v;}public String getEntityKey(){return entityKey;}public void setEntityKey(String v){entityKey=v;}public long getRevision(){return revision;}public void setRevision(long v){revision=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getDefinitionJson(){return definitionJson;}public void setDefinitionJson(String v){definitionJson=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}}
